INSERT INTO `activities` (`id`, `title`, `desc`, `icon`, `color`, `order`, `created_at`, `updated_at`, `image`) VALUES
(1, 'Belajar Mengenal Huruf Dasar', 'Mengenalkan huruf abjad dengan metode visual, lagu, dan permainan edukatif interaktif.', 'font-case', 'from-pink-500 to-rose-500', 1, '2026-08-14 07:13:35', '2026-08-14 07:13:35', NULL),
(2, 'Belajar Mengenal Huruf Hijaiyah', 'Pembiasaan bacaan Iqro & pengenalan huruf Hijaiyah sejak dini dengan cara yang menyenangkan.', 'book-open', 'from-purple-500 to-indigo-500', 2, '2026-08-14 07:13:35', '2026-08-14 07:13:35', NULL),
(3, 'Bermain Motorik Halus & Kasar', 'Stimulasi ketangkasan, koordinasi mata-tangan, keseimbangan, serta stimulasi fisik tumbuh kembang.', 'puzzle-piece', 'from-cyan-500 to-blue-500', 3, '2026-08-14 07:13:35', '2026-08-14 07:13:35', NULL),
(4, 'Menggambar dan Mewarnai', 'Mengasah imajinasi, mengekspresikan seni warna, dan melatih konsentrasi jari jemari anak.', 'paint-brush', 'from-amber-400 to-orange-500', 4, '2026-08-14 07:13:35', '2026-08-14 07:13:35', NULL),
(5, 'Makan Bersama', 'Menanamkan adab berdoa sebelum & sesudah makan, kemandirian menyuap, dan pola makan sehat.', 'cake', 'from-emerald-500 to-teal-600', 5, '2026-08-14 07:13:35', '2026-08-14 07:13:35', NULL),
(6, 'Tidur Siang', 'Istirahat teratur di kamar tidur yang nyaman, bersih, ber-AC, dan terpantau dengan penuh kasih sayang.', 'moon', 'from-violet-500 to-fuchsia-600', 6, '2026-08-14 07:13:35', '2026-08-14 07:13:35', NULL);

