INSERT INTO `facilities` (`id`, `title`, `desc`, `image`, `tag`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Area Bermain Nyaman & Ber-AC', 'Ruangan ber-AC yang dingin, bersih, dan luas agar anak bebas bermain tanpa merasa gerah.', 'images/play-area.png', 'Kenyamanan Utama', 1, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(2, 'Alat Penunjang Edukatif (APE)', 'Mainan edukasi lengkap penunjang tumbuh kembang motorik, logika, dan sensorik anak.', 'images/learning-hijaiyah.png', 'Edukasi & Stimulasi', 2, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(3, 'Ruang Makan Representatif', 'Tempat makan bersih, berestetika, dan higienis khusus anak untuk makan bersama dengan menyenangkan.', 'images/dining-kitchen.png', 'Kesehatan & Adab', 3, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(4, 'Kamar Tidur', 'Kasur empuk, wangi, sprei bersih, dan suasana tenang untuk tidur siang yang berkualitas.', 'images/bedroom.png', 'Istirahat Nyaman', 4, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(5, 'Dapur & Lemari Es', 'Fasilitas dapur dan kulkas untuk menyimpan serta menyiapkan MPASI, susu, & makanan anak secara higienis.', 'images/dining-kitchen.png', 'Higienis & Steril', 5, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(6, 'Toilet (Heater & Cooler)', 'Kamar mandi bersih khusus anak yang dilengkapi pemanas dan pendingin air (Water Heater & Cooler).', 'images/bathroom.png', 'Fasilitas Modern', 6, '2026-08-14 07:13:35', '2026-08-14 07:13:35');

DROP TABLE IF EXISTS `faqs`;
CREATE TABLE IF NOT EXISTS `faqs` (
  `id` bigint(20) UNSIGNED NOT NULL AUTO_INCREMENT,
  `question` text NOT NULL,
  `answer` text NOT NULL,
  `order` int(11) NOT NULL DEFAULT 0,
  `created_at` timestamp NULL DEFAULT NULL,
  `updated_at` timestamp NULL DEFAULT NULL,
  PRIMARY KEY (`id`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_unicode_ci;

INSERT INTO `faqs` (`id`, `question`, `answer`, `order`, `created_at`, `updated_at`) VALUES
(1, 'Berapa biaya pendaftaran TPA Robbani?', 'Biaya pendaftaran awal adalah sebesar Rp 200.000,- yang sudah mencakup formulir registrasi dan penyiapan berkas ananda.', 1, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(2, 'Apa saja usia anak yang dapat dititipkan di TPA Robbani?', 'TPA Robbani menerima bayi & balita (mulai usia 3 bulan hingga usia prasekolah/PAUD).', 2, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(3, 'Bagaimana fasilitas pengasuhan dan keamanan di TPA Robbani?', 'Semua ruangan dilengkapi AC, kasur tidur bersih, dapur higienis, toilet ber-heater/cooler, APE edukatif, dan didampingi pengasuh yang penyayang dan berpengalaman.', 3, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(4, 'Di mana lokasi TPA Robbani?', 'TPA Robbani memiliki 2 lokasi di Indralaya Utara, Kab. Ogan Ilir: TPA Pusat di Jl Sarjana Blok C17 Timbangan, dan TPA Cabang di Griya Sejahtera 7 A4 No. 5.', 4, '2026-08-14 07:13:35', '2026-08-14 07:13:35'),
(5, 'Bagaimana cara mendaftar secara online?', 'Bunda / Ayah dapat langsung mengisi formulir pendaftaran di bagian bawah website ini. Setelah dikirim, Anda akan langsung terhubung ke WhatsApp pengasuh TPA Robbani.', 5, '2026-08-14 07:13:35', '2026-08-14 07:13:35');

